async function startGuest(name,pid,code,skipJoin=false){
 clearTimeout(guestPollTimer);const generation=++roomGeneration;
 stateRevision=-1;pollFailures=0;
 try{if(!skipJoin){const result=await api('/api/join',{code,id:pid,name});if(generation!==roomGeneration)return;acceptRoom(result)}}catch(e){if(mobileRunInput()&&generation!==roomGeneration)return;toast(e.message);home();return}
 const poll=async()=>{
  if(generation!==roomGeneration)return;
  try{
   if(!pollInFlight&&queuedActions===0){
    pollInFlight=true;
    const result=await api(`/api/poll?code=${encodeURIComponent(code)}&id=${encodeURIComponent(pid)}&after=${stateRevision}`);
    if(generation!==roomGeneration)return;
    if(result.unchanged)setConnectionIssue('');else acceptRoom(result);
    pollFailures=0;
   }
  }catch(e){if(mobileRunInput()&&(generation!==roomGeneration||document.hidden))return;pollFailures++;if(!mobileRunInput()||pollFailures>=2)setConnectionIssue(navigator.onLine?e.message:'Your device is offline')}
  finally{pollInFlight=false;if(generation===roomGeneration)guestPollTimer=setTimeout(poll,document.hidden?2000:state?.phase==='run'?200:400)}
 };
 await poll();
}
function send(message){
 if(['place','finishBuild'].includes(message.type)&&state?.buildIntro&&state.buildIntro.until>syncedNow())return;
 const player=state?.players?.find(p=>p.id===state.me);if(player&&['move','turn','aim','shoot','ability','dodge'].includes(message.type))message={...message,scene:combatScene(state,player)};
 const repeatable=['move','turn','aim'].includes(message.type);
 const key=repeatable?null:JSON.stringify(message);
 if((repeatable||message.type==='shoot')&&queuedActions>=2)return;
 if(key&&pendingActionKeys.has(key))return;
 if(queuedActions>=32)return toast('Your last actions are still syncing. Please wait a moment.');
 if(state?.announcement?.until>Date.now()&&['move','turn','aim','shoot','rally'].includes(message.type))return;
 if(connectionIssue)return toast('Reconnecting. Wait for the connection warning to clear.');
 if(!profile?.code)return toast('Join a room first.');
 const room={code:profile.code,id:profile.id,generation:roomGeneration};
 queuedActions++;if(key)pendingActionKeys.add(key);
 let settle;const completion=new Promise(resolve=>{settle=resolve});
 actionQueue.push({message,key,room,settle});
 queueMicrotask(drainActions);
 return completion;
}
async function drainActions(){
 if(actionDrainRunning)return;actionDrainRunning=true;
 try{while(actionQueue.length){
  const batch=[actionQueue.shift()],first=batch[0];
  // Only placement commands may be batched. Preserve their order and all server validation.
  if(first.message.type==='place')while(batch.length<8&&actionQueue[0]?.message.type==='place'&&actionQueue[0].room.generation===first.room.generation)batch.push(actionQueue.shift());
  try{
   if(first.room.generation!==roomGeneration)continue;const player=state?.players?.find(p=>p.id===state.me);if(first.message.scene&&player&&first.message.scene!==combatScene(state,player))continue;
   const payload={code:first.room.code,id:first.room.id};
   if(batch.length>1)payload.actions=batch.map(item=>item.message);else payload.action=first.message;
   const result=await api('/api/action',payload);
   if(first.room.generation!==roomGeneration)continue;
   acceptRoom(result);
   if(result.errors?.length)toast(result.errors.map(error=>error.message).filter((message,i,all)=>all.indexOf(message)===i).join(' '));
  }catch(error){if(/fetch|network|unavailable|retry/i.test(error.message))setConnectionIssue(error.message);else if(first.message.type==='shoot')showShotFeedback(error.message);else toast(error.message)}
  finally{queuedActions-=batch.length;for(const item of batch){if(item.key)pendingActionKeys.delete(item.key);item.settle?.()}}
 }}finally{actionDrainRunning=false}
}
window.addEventListener('offline',()=>setConnectionIssue('Your device is offline'));
