async function api(path,data){let res=await fetch(path,{method:data?'POST':'GET',headers:data?{'content-type':'application/json'}:undefined,body:data?JSON.stringify(data):undefined,cache:'no-store',signal:AbortSignal.timeout(mobileRunInput()?12000:6000)});let result=await res.json().catch(()=>({error:'Room service returned an unreadable response.'}));if(!res.ok)throw Error(result.error||`Room service error (${res.status}).`);return result}

function buildClock(){return '<div class="build-clock"><span>TIME LEFT</span><strong id="phaseClock">3:00</strong></div>'}
function bindDuelActions(){for(const b of app.querySelectorAll('[data-duel-action]'))b.onclick=()=>{const a=state?.pvpArena;if(a?.turnBased)send({type:'duel',realm:a.id,turn:a.turn,action:b.dataset.duelAction})}}
function startClock(){bindDuelActions();clearInterval(clockTimer);if(!state?.deadline)return;const tick=()=>{let el=$('#phaseClock');if(!el)return;let now=Date.now(),paused=state.announcement?.until>now,left=Math.max(0,Math.ceil((state.deadline-(paused?state.announcement.until:now))/1000));let announcement=$('#announcementCountdown');if(announcement)announcement.textContent=`Raid resumes in ${Math.max(0,Math.ceil((state.announcement.until-now)/1000))}…`;el.textContent=`${Math.floor(left/60)}:${String(left%60).padStart(2,'0')}`;el.classList.toggle('urgent',left<=10)};tick();clockTimer=setInterval(tick,250)}

