function monsterSpec(id){return MONSTERS[id]||MONSTERS[floorTheme().roster[0]]}
function monsterMotion(ai,realm=false,now=Date.now()){
 const hit=ai?.hitAt||0,attack=ai?.attackAt||0,move=ai?.movedAt||0;
 if(hit&&now-hit<520)return 'hurt';
 if(attack&&now-attack<620)return 'attack';
 if(realm&&ai?.windupAt>0||!realm&&ai?.state==='windup')return 'windup';
 if(move&&now-move<820)return 'move';
 return 'idle';
}
function monsterSprite(id,small=false){let spec=monsterSpec(id);return `<span class="monster-sprite ${small?'monster-mini':''}" role="img" aria-label="${esc(spec.name)}"><img src="/assets/monsters/${spec.asset}.webp" alt="${esc(spec.name)}" loading="eager" decoding="async" draggable="false"></span>`}
function trapSpec(r,team,k){let id=r.trapTypes?.[team]?.[k]||'duel';return{id,icon:id==='rift'?'✦':'⚔️',name:id==='rift'?'Realm Challenge':'Monster Pit',detail:id==='rift'?'One raider faces a Realm guardian while everyone else keeps playing.':'Teleports one raider into a one-on-one monster fight.'} }

const DIRECTIONS=[[0,-1],[1,0],[0,1],[-1,0]],DIRECTION_NAMES=['NORTH','EAST','SOUTH','WEST'];
function runnerDirectionStyle(p){const screen=mazeScreenDirection(DIRECTIONS[facingOf(p)]),mirror=screen[0]||p.lookFacing||1,angle=Math.atan2(screen[1],screen[0])*180/Math.PI;return `--hero-mirror:${mirror<0?-1:1};--look-angle:${angle}deg`}
let lastLookTurn=0;
function lookTurn(delta){const p=state?.players.find(p=>p.id===state.me);if(state?.phase!=='run'||!p||p.escaped||p.eliminated||state.announcement?.until>Date.now()||document.querySelector('.audio-settings-dialog[open]')||Date.now()-lastLookTurn<140)return;lastLookTurn=Date.now();send({type:'turn',delta:onPortraitMaze()?-delta:delta})}
function lookControls(){return ''}
function facingOf(p){return Number.isInteger(p?.facing)?p.facing:1}

function relativeCell(p,forward,side=0){let facing=facingOf(p),front=DIRECTIONS[facing],right=DIRECTIONS[(facing+1)%4];return[p.x+front[0]*forward+right[0]*side,p.y+front[1]*forward+right[1]*side]}
function inRealm(p){return Boolean(state.pvpArena?.participants?.includes(p?.id))}
function cellAt(team,x,y,me){let size=inRealm(me)?7:(state.mazeSize||7),height=inRealm(me)?7:(state.mazeHeight||size);if(x<0||x>=size||y<0||y>=height)return'wall';let cells=inRealm(me)?state.arenaMaze:state.mazes[team];return cells?.[`${x},${y}`]||''}
function cameraDistance(me,x,y,range,team){let front=DIRECTIONS[facingOf(me)],right=DIRECTIONS[(facingOf(me)+1)%4],dx=x-me.x,dy=y-me.y,forward=dx*front[0]+dy*front[1],side=dx*right[0]+dy*right[1];if(forward<1||forward>range||Math.abs(side)>Math.max(1,Math.floor((forward+1)/2)))return null;let cells=inRealm(me)?state.arenaMaze:state.mazes[team],steps=Math.max(Math.abs(dx),Math.abs(dy));for(let i=1;i<steps;i++){let tx=Math.round(me.x+dx*i/steps),ty=Math.round(me.y+dy*i/steps);if(cells?.[`${tx},${ty}`]==='wall')return null}return{distance:forward,side,screenX:Math.max(36,Math.min(64,50+side/Math.max(1,forward)*22))}}
function frontTarget(me,team){if(!me)return null;const weapon=weaponStats(me),range=weapon.range+(me.character==='witch'&&weapon.range>1?1:0),realm=inRealm(me),candidates=[];
 if(realm&&state.pvpArena.type==='rival'){for(const player of state.players.filter(p=>p.id!==me.id&&inRealm(p)&&p.team!==me.team&&!p.eliminated&&!p.escaped)){const aim=cameraDistance(me,player.x,player.y,range,team);if(aim)candidates.push({type:'player',player,...aim})}}
 else if(realm&&state.pvpArena.type==='monster'){const m=state.pvpArena.monster,aim=m&&m.hp>0&&cameraDistance(me,m.x,m.y,range,team);if(aim)candidates.push({type:'monster',x:m.x,y:m.y,hp:m.hp,id:m.id,spec:monsterSpec(m.id),realm:true,...aim})}
 else{for(const [k,v] of Object.entries(state.mazes[team]||{})){if(v!=='monster')continue;const [x,y]=k.split(',').map(Number),aim=cameraDistance(me,x,y,range,team);if(aim){const id=state.monsterTypes?.[team]?.[k]||floorTheme().roster[0];candidates.push({type:'monster',x,y,hp:state.monsterHp?.[team]?.[k]||0,id,spec:monsterSpec(id),...aim})}}}
 candidates.sort((a,b)=>a.distance-b.distance||Math.abs(a.side)-Math.abs(b.side));return candidates[0]||null;
}
function attackGeometry(me,x,y,team){const weapon=WEAPONS[me.weapon]||WEAPONS.arrow,range=weapon.range+(me.character==='witch'&&weapon.range>1?1:0),cells=inRealm(me)?state.arenaMaze:state.mazes[team],dx=x-me.x,dy=y-me.y,choices=[];for(let facing=0;facing<4;facing++){const front=DIRECTIONS[facing],right=DIRECTIONS[(facing+1)%4],forward=dx*front[0]+dy*front[1],side=dx*right[0]+dy*right[1];if(forward<1||forward>range||Math.abs(side)>Math.max(1,Math.floor((forward+1)/2)))continue;const steps=Math.max(Math.abs(dx),Math.abs(dy));let blocked=false;for(let i=1;i<steps;i++){const tx=Math.round(me.x+dx*i/steps),ty=Math.round(me.y+dy*i/steps);if(cells?.[`${tx},${ty}`]==='wall'){blocked=true;break}}if(!blocked){const clockwise=(facing-facingOf(me)+4)%4,turns=clockwise===3?1:clockwise;choices.push({facing,distance:forward,side,turns})}}choices.sort((a,b)=>a.distance-b.distance||Math.abs(a.side)-Math.abs(b.side)||a.turns-b.turns);return choices[0]||null}
function attackTargets(me,team){if(!me||!state||state.phase!=='run')return[];const targets=[];if(inRealm(me)&&state.pvpArena?.type==='rival'){for(const player of state.players.filter(p=>p.id!==me.id&&inRealm(p)&&p.team!==me.team&&!p.eliminated&&!p.escaped)){const aim=attackGeometry(me,player.x,player.y,team);if(aim)targets.push({type:'player',player,...aim})}}else if(inRealm(me)&&state.pvpArena?.type==='monster'){const m=state.pvpArena.monster;if(m?.hp>0){const aim=attackGeometry(me,m.x,m.y,team);if(aim)targets.push({type:'monster',x:m.x,y:m.y,...aim})}}else for(const[k,v]of Object.entries(state.mazes[team]||{})){if(v!=='monster')continue;const[x,y]=k.split(',').map(Number),aim=attackGeometry(me,x,y,team);if(aim)targets.push({type:'monster',x,y,...aim})}return targets.sort((a,b)=>a.distance-b.distance||Math.abs(a.side)-Math.abs(b.side))}
function firstPersonView(team,me){return dungeonView(team,me)}
