const wardenVisits=new Set();
function firstWardenVisit(room){const key=(room?.code||state?.code||'')+':'+(room?.me||state?.me||'');if(wardenVisits.has(key))return false;wardenVisits.add(key);try{const saved='trapboundStoryVisit161:'+key;if(sessionStorage.getItem(saved))return false;sessionStorage.setItem(saved,'1')}catch{}return true}
function openWardenTutorial(){if(state?.phase!=='lobby')return;tutorialReturnFocus=document.activeElement;tutorialOpen=true;tutorialClosing=false;howOpen=false;tutorialStep=0;tutorialTextAt=Date.now();tutorialChanging=false;render();requestAnimationFrame(()=>document.querySelector('[data-warden-next]')?.focus())}
function closeWardenTutorial(){if(tutorialClosing)return;clearTimeout(tutorialTransitionTimer);tutorialClosing=true;const entry=tutorialEntrySerial;document.querySelector('.warden-overlay')?.classList.add('tutorial-leaving');tutorialTransitionTimer=setTimeout(()=>{if(entry!==tutorialEntrySerial)return;tutorialOpen=false;tutorialChanging=false;tutorialClosing=false;render();requestAnimationFrame(()=>document.querySelector('[data-character].selected')?.focus())},140)}

function changeWardenScene(delta){if(tutorialChanging||tutorialClosing)return;const next=tutorialStep+delta;if(next>=WARDEN_SCENES.length)return closeWardenTutorial();if(next<0)return;tutorialChanging=true;render();tutorialTransitionTimer=setTimeout(()=>{if(!tutorialOpen)return;tutorialStep=next;tutorialTextAt=Date.now();tutorialChanging=false;render();document.querySelector('[data-warden-next]')?.focus()},80)}
function referenceArt(box,label='',extra=''){const [x,y,w,h]=box.split(' ').map(Number),id='guide-crop-'+[x,y,w,h].join('-'),logo=extra==='reference-logo';return `<svg class="reference-tutorial-art ${extra}" viewBox="${box}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${esc(label)}"><defs><clipPath id="${id}" clipPathUnits="userSpaceOnUse">${logo?`<path d="M${x} ${y}h${w}v${h}H${x+52}v-30h-52Z"/>`:`<rect x="${x}" y="${y}" width="${w}" height="${h}"/>`}</clipPath></defs><image href="/assets/tutorial-v145/reference.png" width="1536" height="1024" clip-path="url(#${id})"/></svg>`}
