function enhanceRaidUI(){let scene=app.querySelector('.dungeon-scene');if(!scene||state?.phase!=='run')return;let me=state.players.find(p=>p.id===state.me),weapon=weaponStats(me),runner=app.querySelector('.runner-self');if(runner&&!runner.querySelector('.weapon-stats'))runner.insertAdjacentHTML('beforeend',`<small class="weapon-stats">${weapon.damage} damage · ${weapon.range+(me?.character==='witch'&&weapon.range>1?1:0)} tile range${weapon.cooldown?` · ${weapon.cooldown}ms cooldown`:''}</small>`);let controls=app.querySelector('.fp-controls');if(controls&&state.teamTrial?.team===me?.team&&!controls.querySelector('[data-rally]')){let b=document.createElement('button');b.className='rally';b.dataset.rally='';b.innerHTML='🤝<small>Rally team (R)</small>';b.onclick=()=>send({type:'rally'});controls.insertBefore(b,controls.lastElementChild)}let cross=scene.querySelector('.scene-reticle');if(!cross)return;let choose=e=>{let box=scene.getBoundingClientRect(),ratio=(e.clientX-box.left)/box.width,next=ratio<.42?-1:ratio>.58?1:0;if(next!==Number(me?.aimLane||0)){me.aimLane=next;send({type:'aim',lane:next})}};scene.onpointerdown=choose;scene.onpointermove=e=>{if(e.buttons||e.pointerType==='touch')choose(e)};for(let b of app.querySelectorAll('[data-aim]'))b.classList.toggle('selected',+b.dataset.aim===Number(me?.aimLane||0))}
