function enhanceCoopUI(){if(state?.phase==='lobby'){let card=[...app.querySelectorAll('.card')].find(x=>x.querySelector('h2')?.textContent==='How to play');if(card){let intro=card.querySelector('p');if(intro)intro.textContent='Both teams build together, then raid only the opposing team’s maze. A hidden gate can send one player into a fair 1v1 rival or monster encounter.';let list=card.querySelector('ol');if(list&&!list.querySelector('.dm-rule')){let item=document.createElement('li');item.className='dm-rule';item.textContent='The Warden may appear once during a floor with a random curveball. The twist affects both teams equally, and everyone gets the same brief pause.';list.append(item)}}}if(state?.phase==='build'){let team=state.players.find(p=>p.id===state.me)?.team||0,banner=app.querySelector('.build-banner'),ready=state.buildReady?.[team];if(banner){let kicker=banner.querySelector('.kicker'),heading=banner.querySelector('h2'),copy=banner.querySelector('p');if(kicker)kicker.textContent=`BOTH TEAMS BUILD TOGETHER · ${floorTheme().difficulty}`;if(heading)heading.textContent=`${floorTheme().name} · ${state.message}`;if(copy)copy.textContent=ready?'Your team is ready. The other team has no more than 30 seconds left.':'You have up to 3:00. Build together with 14, 18, then 22 pieces. Hazards and monsters need space; the Dungeon Master safely fills unused route pieces.';for(let b of banner.querySelectorAll('[data-tool]')){b.disabled=!!ready;b.classList.toggle('selected',b.dataset.tool===buildTool)}let finish=banner.querySelector('[data-finish-build]');if(!finish){finish=document.createElement('button');finish.className='btn finish-maze';finish.dataset.finishBuild='';finish.textContent=ready?'Team ready':'Finish Maze';finish.onclick=()=>send({type:'finishBuild'});banner.querySelector('.toolbox')?.append(finish)}else{finish.disabled=!!ready;finish.textContent=ready?'Team ready':'Finish Maze'}if(!banner.querySelector('.team-build-status')){let note=document.createElement('div');note.className='team-build-status';banner.append(note)}let note=banner.querySelector('.team-build-status');if(note)note.textContent=`Amber ${state.buildReady?.[0]?'✓ ready':'building'} · Violet ${state.buildReady?.[1]?'✓ ready':'building'}`}}if(state?.phase==='run'){let status=app.querySelector('.raid-status'),players=state.players,me=players.find(p=>p.id===state.me);if(status){let panel=status.querySelector('.coop-panel');if(!panel){panel=document.createElement('div');panel.className='coop-panel';status.insertBefore(panel,status.firstChild)}let progress=[0,1].map(team=>{let group=players.filter(p=>p.team===team),escaped=group.filter(p=>p.escaped).length;return`${team===0?'Amber':'Violet'} ${escaped}/${group.length}${state.teamEscaped?.[team]?' ✓':''}`}).join(' · '),arena=inRealm(me)?state.pvpArena:null,title=arena?.type==='monster'?'⚔ MONSTER PIT':arena?'⚔ RIVAL REALM':'🤝 TEAM ESCAPE',detail=arena?.type==='monster'?'Defeat the creature before the gate closes':arena?'Win your 1v1 rival duel':`Most living escapes wins · tie: fastest team clear · ${progress}`;panel.innerHTML=`<b>${title}</b><small>${detail}</small>`;let log=status.querySelector('.combat-log');if(!log){log=document.createElement('div');log.className='combat-log';status.append(log)}log.textContent=state.message}}}
enhanceCoopUI();
function enhanceBuildTiles(){if(state?.phase!=='build')return;let team=state.players.find(p=>p.id===state.me)?.team||0,ready=state.buildReady?.[team],size=state.mazeSize||7,[ex,ey]=mazeEnd(size,state.floor);app.querySelectorAll('.maze .tile').forEach((tile,index)=>{let x=index%size,y=Math.floor(index/size);if(!tile.dataset.cell)tile.dataset.cell=`${x},${y}`;tile.disabled=!!ready||x===0&&y===0||x===ex&&y===ey;tile.onclick=()=>{if(!tile.disabled)send({type:'place',x,y,kind:buildTool,monster:app.querySelector('#monsterChoice')?.value})}})}
